import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Certificate> validChain = Arrays.asList(
            new Certificate("MyDSA", "Let's Encrypt R3"),
            new Certificate("Let's Encrypt R3", "ISRG Root X1"),
            new Certificate("ISRG Root X1", "ISRG Root X1")
        );

        List<Certificate> untrustedChain = Arrays.asList(
            new Certificate("evil-site.com", "Fake CA"),
            new Certificate("Fake CA", "Fake CA")
        );

        Set<String> trustedRoots = new HashSet<>(Arrays.asList("ISRG Root X1"));

        System.out.println("Valid chain: " + validateChain(validChain, trustedRoots));
        System.out.println("Untrusted chain: " + validateChain(untrustedChain, trustedRoots));
    }

    static class Certificate {
        String subject;
        String issuer;
        Certificate(String subject, String issuer) {
            this.subject = subject;
            this.issuer = issuer;
        }
    }

    // Every certificate's issuer must match the next certificate's own subject,
    // and the final certificate in the chain must be a genuinely trusted root.
    static String validateChain(List<Certificate> chain, Set<String> trustedRoots) {
        for (int i = 0; i < chain.size() - 1; i++) {
            if (!chain.get(i).issuer.equals(chain.get(i + 1).subject)) {
                return "INVALID, broken link between " + chain.get(i).subject + " and " + chain.get(i + 1).subject;
            }
        }

        Certificate root = chain.get(chain.size() - 1);
        if (!trustedRoots.contains(root.subject)) {
            return "INVALID, root " + root.subject + " is not a trusted authority";
        }

        return "VALID";
    }
}

