class Certificate:
    def __init__(self, subject, issuer):
        self.subject = subject
        self.issuer = issuer


# Every certificate's issuer must match the next certificate's own subject,
# and the final certificate in the chain must be a genuinely trusted root.
def validate_chain(chain, trusted_roots):
    for i in range(len(chain) - 1):
        if chain[i].issuer != chain[i + 1].subject:
            return f"INVALID, broken link between {chain[i].subject} and {chain[i + 1].subject}"

    root = chain[-1]
    if root.subject not in trusted_roots:
        return f"INVALID, root {root.subject} is not a trusted authority"

    return "VALID"


def main():
    valid_chain = [
        Certificate("MyDSA", "Let's Encrypt R3"),
        Certificate("Let's Encrypt R3", "ISRG Root X1"),
        Certificate("ISRG Root X1", "ISRG Root X1"),
    ]

    untrusted_chain = [
        Certificate("evil-site.com", "Fake CA"),
        Certificate("Fake CA", "Fake CA"),
    ]

    trusted_roots = {"ISRG Root X1"}

    print("Valid chain:", validate_chain(valid_chain, trusted_roots))
    print("Untrusted chain:", validate_chain(untrusted_chain, trusted_roots))


if __name__ == "__main__":
    main()

