#include <iostream>
#include <string>
#include <vector>
#include <set>
using namespace std;

struct Certificate {
    string subject;
    string issuer;
    Certificate(const string& subject, const string& issuer) : subject(subject), issuer(issuer) {}
};

// Every certificate's issuer must match the next certificate's own subject,
// and the final certificate in the chain must be a genuinely trusted root.
string validateChain(const vector<Certificate>& chain, const set<string>& trustedRoots) {
    for (size_t i = 0; i + 1 < chain.size(); i++) {
        if (chain[i].issuer != chain[i + 1].subject) {
            return "INVALID, broken link between " + chain[i].subject + " and " + chain[i + 1].subject;
        }
    }

    const Certificate& root = chain.back();
    if (trustedRoots.find(root.subject) == trustedRoots.end()) {
        return "INVALID, root " + root.subject + " is not a trusted authority";
    }

    return "VALID";
}

int main() {
    vector<Certificate> validChain = {
        Certificate("MyDSA", "Let's Encrypt R3"),
        Certificate("Let's Encrypt R3", "ISRG Root X1"),
        Certificate("ISRG Root X1", "ISRG Root X1"),
    };

    vector<Certificate> untrustedChain = {
        Certificate("evil-site.com", "Fake CA"),
        Certificate("Fake CA", "Fake CA"),
    };

    set<string> trustedRoots = {"ISRG Root X1"};

    cout << "Valid chain: " << validateChain(validChain, trustedRoots) << endl;
    cout << "Untrusted chain: " << validateChain(untrustedChain, trustedRoots) << endl;

    return 0;
}
